import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const flags = vi.hoisted(() => ({ v2: false }));
vi.mock("../src/flags", () => ({
  FLAGS: { notifRouterV2: "notif_router_v2" },
  flag: () => flags.v2,
}));

import { routeDeepLink } from "../src/notifications/router";
import { hydrate, resetSessionForTests } from "../src/store/session";

describe("router v2 bug reproduction", () => {
  beforeEach(() => {
    flags.v2 = true;
    resetSessionForTests();
    vi.useFakeTimers();
  });
  afterEach(() => vi.useRealTimers());

  it("crashes when tapping push notification before session hydrates", () => {
    const navigate = vi.fn();
    // Start hydration with ~350ms delay (simulating IndexedDB restore)
    void hydrate({ delayMs: 350 });
    // Immediately tap a push notification (before hydration completes)
    const routedPromise = routeDeepLink("/ride/abc", navigate, "push");
    // Advance timers slightly but NOT past hydration delay
    return vi.advanceTimersByTimeAsync(100).then(() => {
      // The routeV2 should have crashed by now trying to access state.session!.riderId
      // when session is still undefined (hydrated: false)
      return expect(routedPromise).rejects.toThrow("Cannot read properties of undefined (reading 'riderId')");
    });
  });
});

